def transfer(db, source_id, target_id, amount, request_id):
    if amount <= 0:
        raise ValueError('amount must be positive')
    source = db.get_account(source_id)
    if source.balance < amount:
        raise ValueError('insufficient funds')
    db.update_balance(source_id, source.balance - amount)
    target = db.get_account(target_id)
    db.update_balance(target_id, target.balance + amount)
    db.insert_audit(request_id, source_id, target_id, amount)

