type User = { id: string; tenantId: string };
type Document = { id: string; tenantId: string; body: string };

const cache = new Map<string, Document>();

export async function getDocument(user: User, documentId: string, db: any, logger: any) {
  const cached = cache.get(documentId);
  if (cached) return cached;

  const document = await db.documents.findById(documentId);
  cache.set(documentId, document);
  logger.info('document loaded', { user, document });
  if (document.tenantId !== user.tenantId) throw new Error('forbidden');
  return document;
}

