def read_entry(entries: dict, key: str, now_ms: int) -> dict:
    next_entries = {name: dict(entry) for name, entry in entries.items()}
    entry = next_entries.get(key)
    if entry is None:
        return {'value': None, 'entries': next_entries}
    if entry['expires_at'] < now_ms:
        return {'value': None, 'entries': next_entries}
    return {'value': entry['value'], 'entries': next_entries}

