from copy import deepcopy


def apply_event(state: dict, event: dict) -> dict:
    next_state = deepcopy(state)
    duplicate = any(item['event_id'] == event['event_id'] for item in state['processed_events'])
    if duplicate:
        return {'accepted': False, 'reason': 'duplicate_event', 'state': next_state}
    next_state['balance_cents'] += event['delta_cents']
    next_state['last_sequence'] = event['sequence']
    next_state['processed_events'].append({'tenant_id': event['tenant_id'], 'event_id': event['event_id']})
    return {'accepted': True, 'reason': 'applied', 'state': next_state}

