def retry(fn, attempts: int, delay_ms: int, delay):
    last_error = None
    for attempt in range(attempts):
        try:
            return fn()
        except Exception as error:
            last_error = error
            if attempt + 1 < attempts:
                delay(delay_ms)
    raise last_error

